/**
 * Owner's directive, 2026-11-26 ("OPERAÇÃO BLACK FRIDAY 2026"): service
 * layer for the independent, manual Black Friday 2026 catalog — see
 * prisma/schema.prisma's BlackFridayProduct/BlackFridayCreative doc
 * comments. Deliberately separate from vitrine-link-register.ts /
 * affiliate-link-registry.ts: this campaign's links are never generated by
 * this project (owner's rule: "não invente links de afiliado"), only
 * pasted and checked.
 */
import { prisma } from "@/lib/db";
import type { BlackFridayProduct, BlackFridayProductStatus } from "@prisma/client";
import {
  expectedIdsFromProductUrl,
  decideVerdict,
  titleSimilarity,
  titleJaccard,
  EXACT_TITLE_JACCARD,
  type LinkCheckVerdict,
} from "@/lib/services/ml-panel-check-logic";
import { openBlackFridayAffiliateLink } from "@/lib/services/ml-panel-check";

const MELI_HOSTS = /^(www\.)?(mercadolivre\.com(\.br)?|meli\.la)$/i;

export interface BlackFridayCandidateCreative {
  id: string;
  storedPath: string;
  originalFilename: string;
  sha256: string;
}

export interface BlackFridayPanelRow extends BlackFridayProduct {
  selectedCreative: BlackFridayCandidateCreative | null;
  candidates: BlackFridayCandidateCreative[];
}

export interface BlackFridayCounters {
  total: number;
  pendingLink: number;
  linkPasted: number;
  validated: number;
  divergent: number;
  rejected: number;
  disabled: number;
  missingCreative: number;
  xmlEligible: number;
}

function isXmlEligible(p: BlackFridayProduct): boolean {
  return (
    p.enabled &&
    p.status === "VALIDATED" &&
    !!p.affiliateUrl &&
    !!p.mlUrlOriginal &&
    !!p.selectedCreativeId
  );
}

export interface BlackFridaySurplusCreative {
  id: string;
  groupKey: string;
  storedPath: string;
  originalFilename: string;
  sha256: string;
}

export async function loadBlackFridayPanel(): Promise<{
  rows: BlackFridayPanelRow[];
  counters: BlackFridayCounters;
  /** Owner's directive, section 7 ("se algum criativo não corresponder a
   * nenhum dos 30 produtos, mantenha-o separado e identificado como
   * excedente"): creatives imported from Henrique's files that no
   * official slot's creativeGroupKey points to — never deleted, just
   * surfaced separately so they're never silently lost or confused with
   * a real candidate. */
  surplusCreatives: BlackFridaySurplusCreative[];
}> {
  const [products, creatives] = await Promise.all([
    prisma.blackFridayProduct.findMany({
      orderBy: { slotNumber: "asc" },
      include: { selectedCreative: true },
    }),
    prisma.blackFridayCreative.findMany(),
  ]);

  const byGroup = new Map<string, typeof creatives>();
  for (const c of creatives) {
    const list = byGroup.get(c.groupKey) ?? [];
    list.push(c);
    byGroup.set(c.groupKey, list);
  }

  const rows: BlackFridayPanelRow[] = products.map((p) => ({
    ...p,
    candidates: (byGroup.get(p.creativeGroupKey) ?? []).map((c) => ({
      id: c.id,
      storedPath: c.storedPath,
      originalFilename: c.originalFilename,
      sha256: c.sha256,
    })),
  }));

  const usedGroupKeys = new Set(products.map((p) => p.creativeGroupKey));
  const surplusCreatives: BlackFridaySurplusCreative[] = creatives
    .filter((c) => !usedGroupKeys.has(c.groupKey))
    .map((c) => ({
      id: c.id,
      groupKey: c.groupKey,
      storedPath: c.storedPath,
      originalFilename: c.originalFilename,
      sha256: c.sha256,
    }));

  const counters: BlackFridayCounters = {
    total: products.length,
    pendingLink: products.filter((p) => p.status === "PENDING_LINK").length,
    linkPasted: products.filter((p) => p.status === "LINK_PASTED").length,
    validated: products.filter((p) => p.status === "VALIDATED").length,
    divergent: products.filter((p) => p.status === "DIVERGENT").length,
    rejected: products.filter((p) => p.status === "REJECTED").length,
    disabled: products.filter((p) => !p.enabled).length,
    missingCreative: products.filter((p) => (byGroup.get(p.creativeGroupKey) ?? []).length === 0).length,
    xmlEligible: products.filter(isXmlEligible).length,
  };

  return { rows, counters, surplusCreatives };
}

export class BlackFridayUpdateError extends Error {}

export interface BlackFridayLinkCheck {
  status: LinkCheckVerdict | "invalid";
  message: string;
  linkTitle: string | null;
  profileOk: boolean | null;
}

/** Owner's rule: "não considere suficiente receber HTTP 200... confirme o
 * destino comercial efetivo." Opens the pasted affiliate link for real and
 * compares the product it actually resolves to against mlUrlOriginal. */
export async function checkBlackFridayLink(input: {
  productName: string;
  mlUrlOriginal: string | null;
  affiliateUrl: string;
}): Promise<BlackFridayLinkCheck> {
  let url: URL;
  try {
    url = new URL(input.affiliateUrl);
  } catch {
    return { status: "invalid", message: "Isso não parece um link.", linkTitle: null, profileOk: null };
  }
  if (!MELI_HOSTS.test(url.hostname)) {
    return {
      status: "invalid",
      message: "Esse link não é do Mercado Livre.",
      linkTitle: null,
      profileOk: null,
    };
  }

  const opened = await openBlackFridayAffiliateLink(input.affiliateUrl);
  const expected = expectedIdsFromProductUrl(input.mlUrlOriginal ?? undefined);
  const similarity = opened.title ? titleSimilarity(input.productName, opened.title) : null;
  const status = decideVerdict({
    expectedCatalogId: expected.catalogId,
    resolvedCatalogId: opened.catalogId,
    similarity,
    exactTitle:
      !!opened.title && titleJaccard(input.productName, opened.title) >= EXACT_TITLE_JACCARD,
  });

  const messages: Record<LinkCheckVerdict, string> = {
    match: "Confere: o link leva ao mesmo produto anunciado.",
    likely: "Provavelmente é o mesmo produto (o título bate). Compare antes de validar.",
    mismatch: "ATENÇÃO: o link leva a OUTRO produto ou ao perfil do afiliado — não valide.",
    unknown: "Não consegui ler o produto do link (pode ser a página de perfil do Mercado Livre). Confirme manualmente antes de validar.",
  };

  return { status, message: messages[status], linkTitle: opened.title, profileOk: opened.profileOk };
}

export interface BlackFridayUpdateInput {
  mlUrlOriginal?: string | null;
  affiliateUrl?: string | null;
  currentPrice?: number | null;
  selectedCreativeId?: string | null;
  status?: BlackFridayProductStatus;
  reviewNote?: string | null;
  markDestinationChecked?: boolean;
  /** Owner's directive, section 10 ("Possibilidade de desativar
   * individualmente o produto") — independent of status, see schema's
   * own doc comment on BlackFridayProduct.enabled. */
  enabled?: boolean;
}

export async function updateBlackFridayProduct(
  id: string,
  input: BlackFridayUpdateInput,
): Promise<BlackFridayProduct> {
  const existing = await prisma.blackFridayProduct.findUnique({ where: { id } });
  if (!existing) throw new BlackFridayUpdateError("Produto não encontrado.");

  if (input.selectedCreativeId) {
    const creative = await prisma.blackFridayCreative.findUnique({
      where: { id: input.selectedCreativeId },
    });
    if (!creative || creative.groupKey !== existing.creativeGroupKey) {
      throw new BlackFridayUpdateError("Criativo não pertence a este produto.");
    }
  }

  return prisma.blackFridayProduct.update({
    where: { id },
    data: {
      ...(input.mlUrlOriginal !== undefined ? { mlUrlOriginal: input.mlUrlOriginal } : {}),
      ...(input.affiliateUrl !== undefined ? { affiliateUrl: input.affiliateUrl } : {}),
      ...(input.currentPrice !== undefined ? { currentPrice: input.currentPrice } : {}),
      ...(input.selectedCreativeId !== undefined ? { selectedCreativeId: input.selectedCreativeId } : {}),
      ...(input.status !== undefined ? { status: input.status } : {}),
      ...(input.enabled !== undefined ? { enabled: input.enabled } : {}),
      ...(input.reviewNote !== undefined ? { reviewNote: input.reviewNote } : {}),
      ...(input.markDestinationChecked ? { destinationCheckedAt: new Date() } : {}),
    },
  });
}

/** Products the XML feed may publish — see isXmlEligible's own rule. */
export async function loadXmlEligibleBlackFridayProducts() {
  const products = await prisma.blackFridayProduct.findMany({
    where: {
      status: "VALIDATED",
      affiliateUrl: { not: null },
      mlUrlOriginal: { not: null },
      selectedCreativeId: { not: null },
    },
    orderBy: { slotNumber: "asc" },
    include: { selectedCreative: true },
  });
  return products.filter(isXmlEligible);
}
